using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;
using System.Windows.Forms;
namespace Overclock {
 sealed class DiskScoreRow {public string Name;public double? Read,Write,ReadIops,WriteIops,ReadLatency,WriteLatency;}
 sealed class DiskScoreData {
  public string Drive="Select a physical drive",Settings="",Status="Ready";public bool IsCopy;public DateTime Utc;public List<DiskScoreRow> Rows=new List<DiskScoreRow>();public bool HasMeasurements{get{return Rows.Any(r=>r.Read.HasValue||r.Write.HasValue);}}
  public static string DriveLabel(string identity){string[] parts=identity.Replace("Physical disk:","").Trim().Split('|');return parts.Length>=4?parts[0].Trim()+" · "+parts[1].Trim()+" · "+parts[3].Trim():identity;}
  public static DiskScoreData FromRecord(RunRecord record){var data=FromReport(record.Report,record.Status);data.Utc=record.Utc;data.IsCopy=record.Kind=="copy";if(data.Drive=="Select a physical drive")data.Drive=DriveLabel((record.Hardware??"").Split('\n')[0]);return data;}
  public static DiskScoreData FromReport(string report,string status){var data=new DiskScoreData{Status=status,Utc=DateTime.UtcNow};string identity=report.Split('\n').FirstOrDefault(l=>l.StartsWith("Physical disk:"));if(identity!=null)data.Drive=DriveLabel(identity);var settings=Regex.Match(report,@"Profile:\s*([0-4])\s*\| seconds:\s*(\d+)\s*\| repetitions:\s*(\d+)");var size=Regex.Match(report,@"Mounted volume:.*?\|\s*(\d+) MiB");if(settings.Success){string[] names={"Default","NVMe","AS SSD inspired","Compression","Custom"};data.Settings=names[int.Parse(settings.Groups[1].Value)]+" · "+(size.Success?size.Groups[1].Value+" MiB · ":"")+settings.Groups[2].Value+" s / phase · "+settings.Groups[3].Value+" measured run(s)";}
   var parsed=ReportStore.Create("display","","",report,status);foreach(string name in parsed.Metrics.Where(m=>m.Unit=="MB/s").Select(m=>Regex.Replace(m.Workload,@"\s+(READ|WRITE)$","")).Distinct()){Func<string,string,double?> metric=(direction,unit)=>{var m=parsed.Metrics.FirstOrDefault(v=>v.Workload==name+" "+direction&&v.Unit==unit);return m==null?(double?)null:m.Value;};var row=new DiskScoreRow{Name=name,Read=metric("READ","MB/s"),Write=metric("WRITE","MB/s"),ReadIops=metric("READ","IOPS"),WriteIops=metric("WRITE","IOPS"),ReadLatency=metric("READ","us"),WriteLatency=metric("WRITE","us")};if(!row.Read.HasValue&&!row.Write.HasValue){var single=parsed.Metrics.FirstOrDefault(v=>v.Workload==name&&v.Unit=="MB/s");if(single!=null)row.Read=single.Value;}data.Rows.Add(row);}data.IsCopy=data.Rows.Any(row=>row.Name.StartsWith("ISO (")||row.Name.StartsWith("Program (")||row.Name.StartsWith("Game ("));if(data.IsCopy)data.Settings=(size.Success?size.Groups[1].Value+" MiB per scenario · ":"")+"Filesystem copy · destination flushed";return data;
  }
 }
 sealed class DiskScoreboard:Control {
  public DiskScoreData Data=new DiskScoreData();public bool Details;public DiskScoreboard(){DoubleBuffered=true;BackColor=Theme.Surface;Height=440;AccessibleName="SSD read and write results";}
  public void RefreshData(DiskScoreData data){Data=data;Height=Math.Max(300,180+Math.Max(1,data.Rows.Count)*68);Invalidate();}
  static string Value(double? value,string format){return value.HasValue?value.Value.ToString(format,CultureInfo.CurrentCulture):"—";}
  static void DrawText(Graphics g,string value,Font font,Rectangle rect,Color color,TextFormatFlags extra=TextFormatFlags.Left){TextRenderer.DrawText(g,value,font,rect,color,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding|extra);}
  public void DrawBoard(Graphics g,Rectangle area){g.SmoothingMode=SmoothingMode.AntiAlias;using(var brush=new SolidBrush(Theme.Surface))g.FillRectangle(brush,area);int pad=20,w=area.Width-pad*2;Branding.DrawLogo(g,new Rectangle(pad,12,200,49));DrawText(g,Data.Status.ToUpperInvariant(),Theme.Face(10,FontStyle.Bold),new Rectangle(area.Width-250,20,230,26),Data.Status=="Completed"?Theme.Secondary:Data.Status=="Ready"?Theme.Muted:Data.Status=="Running"?Theme.Accent:Theme.Warning,TextFormatFlags.Right);DrawText(g,Data.Drive,Theme.Face(12,FontStyle.Bold),new Rectangle(pad,67,w,27),Theme.Text);DrawText(g,Data.Settings,Theme.Face(9),new Rectangle(pad,96,w,23),Theme.Muted);int label=Math.Max(140,w/5),cell=(w-label-16)/2;int y=126;using(var header=new LinearGradientBrush(new Rectangle(pad,y,w,31),Color.FromArgb(200,8,29),Color.FromArgb(100,4,14),90f))g.FillRectangle(header,pad,y,w,31);DrawText(g,"WORKLOAD",Theme.Face(9,FontStyle.Bold),new Rectangle(pad+8,y,label-8,28),Theme.Text);DrawText(g,Data.IsCopy?"COPY THROUGHPUT (MB/s)":"READ  (MB/s)",Theme.Face(11,FontStyle.Bold),new Rectangle(pad+label+8,y,Data.IsCopy?cell*2+8:cell,28),Theme.Text,TextFormatFlags.HorizontalCenter);if(!Data.IsCopy)DrawText(g,"WRITE  (MB/s)",Theme.Face(11,FontStyle.Bold),new Rectangle(pad+label+cell+16,y,cell,28),Theme.Text,TextFormatFlags.HorizontalCenter);y+=34;int rows=Math.Max(1,Data.Rows.Count);int rowHeight=Math.Max(64,(area.Height-208)/rows);double max=Data.Rows.SelectMany(r=>new[]{r.Read??0,r.Write??0}).DefaultIfEmpty(1).Max();if(max<=0)max=1;
   for(int i=0;i<rows;i++){var row=Data.Rows.Count>i?Data.Rows[i]:new DiskScoreRow{Name="No measurements yet"};var name=Regex.Match(row.Name,@"^(.*?)\s+(Q\d+T\d+)$");if(!name.Success)DrawText(g,row.Name,Theme.Face(11,FontStyle.Bold),new Rectangle(pad,y,label-8,rowHeight),Theme.Text);if(name.Success){DrawText(g,name.Groups[1].Value,Theme.Face(11,FontStyle.Bold),new Rectangle(pad,y+10,label-8,25),Theme.Text);DrawText(g,name.Groups[2].Value,Theme.Face(9),new Rectangle(pad,y+35,label-8,22),Theme.Muted);}
    for(int direction=0;direction<(Data.IsCopy?1:2);direction++){double? number=direction==0?row.Read:row.Write;int x=pad+label+8+direction*(cell+8),cw=Data.IsCopy?cell*2+8:cell;var rectangle=new Rectangle(x,y,cw,rowHeight-8);using(var path=Theme.Angular(rectangle,6))using(var brush=new SolidBrush(Theme.Raised))g.FillPath(brush,path);if(number.HasValue){var fill=new Rectangle(x+1,y+1,Math.Max(2,(int)((cw-2)*number.Value/max)),rowHeight-10);using(var brush=new LinearGradientBrush(rectangle,Color.FromArgb(117,37,46),Color.FromArgb(55,26,32),0f))g.FillRectangle(brush,fill);}int valueHeight=Details?rowHeight-27:rowHeight-8;DrawText(g,Value(number,"N2"),Theme.Face(rowHeight>=74?30:26,FontStyle.Bold),new Rectangle(x+10,y,cw-20,valueHeight),Theme.Text,TextFormatFlags.Right);if(Details){var iops=direction==0?row.ReadIops:row.WriteIops;var latency=direction==0?row.ReadLatency:row.WriteLatency;DrawText(g,Value(iops,"N0")+" IOPS  ·  "+Value(latency,"N1")+" µs",Theme.Face(8),new Rectangle(x+10,y+rowHeight-29,cw-20,19),Theme.Muted,TextFormatFlags.Right);}}
    y+=rowHeight;
   }
   string date=Data.Utc==default(DateTime)?"":Data.Utc.ToLocalTime().ToString("dd MMM yyyy · HH:mm");DrawText(g,date+"   ·   Decimal MB/s   ·   "+(Data.IsCopy?"Filesystem copy workload":"Independent DiskSpd workloads"),Theme.Face(8),new Rectangle(pad,area.Height-30,w,22),Theme.Muted);
  }
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);DrawBoard(e.Graphics,ClientRectangle);}
  public Bitmap CreateImage(){int height=216+Math.Max(1,Data.Rows.Count)*94;var bitmap=new Bitmap(1100,height);using(var graphics=Graphics.FromImage(bitmap))DrawBoard(graphics,new Rectangle(0,0,bitmap.Width,bitmap.Height));return bitmap;}
  public void SavePng(string path){using(var image=CreateImage())image.Save(path,ImageFormat.Png);}
  public static void SaveRecord(RunRecord record){using(var dialog=new SaveFileDialog{Filter="Shareable result image|*.png",FileName="BenchMark-X-results.png"})if(dialog.ShowDialog()==DialogResult.OK)try{using(var board=new DiskScoreboard()){board.Data=DiskScoreData.FromRecord(record);board.SavePng(dialog.FileName);}}catch(Exception error){MessageBox.Show(error.Message,"Could not export image");}}
 }
}

